inline int Index(WCHAR c){return c>=L'0'&&c<=L'9'?int(c-L'0'):-1;}
inline int InkHeight(int mode,const WCHAR* text,int pixels){
    const auto& face=faces[Limit(mode,0,2)][Limit(pixels,7,48)-7];int top=128,bottom=0;
    for(unsigned i=0;text[i];++i){int n=Index(text[i]);if(n<0)return 0;const auto& g=face.glyphs[n];if(g.top<top)top=g.top;if(g.bottom>bottom)bottom=g.bottom;}
    return bottom>top?bottom-top:0;
}
// Kudo has a smaller visible numeral inside its em. Match the original ink
// height before width fitting; the cat font keeps its decorative ear silhouette.
inline int PreferredPixels(int mode,const WCHAR* text,int pixels){
    pixels=Limit(pixels,7,48);if(mode!=1)return pixels;
    int target=InkHeight(0,text,pixels),best=pixels,error=128;
    for(int candidate=7;candidate<=48;++candidate){int delta=InkHeight(mode,text,candidate)-target;if(delta<0)delta=-delta;if(delta<error){best=candidate;error=delta;}}
    return best;
}
// TextSize supplies actual engine advances/line height. Map glyph ink into that line.
inline bool Bounds(int mode,const WCHAR* text,int pixels,int lineWidth,int lineHeight,int& left,int& top,int& wide,int& tall){
    const auto& face=faces[Limit(mode,0,2)][Limit(pixels,7,48)-7];int pen=0,minX=0,maxX=0,minY=0,maxY=0;bool first=true;
    for(unsigned i=0;text[i];++i){int index=Index(text[i]);if(index<0)return false;const auto& g=face.glyphs[index];int lo=pen+g.left*256,hi=pen+g.right*256;
        if(first||lo<minX)minX=lo;if(first||hi>maxX)maxX=hi;if(first||g.top<minY)minY=g.top;if(first||g.bottom>maxY)maxY=g.bottom;first=false;pen+=g.advance256;}
    if(first||!pen)return false;
    left=(minX*lineWidth+pen/2)/pen;int right=(maxX*lineWidth+pen/2)/pen;
    top=(minY*lineHeight+face.lineHeight/2)/face.lineHeight;int bottom=(maxY*lineHeight+face.lineHeight/2)/face.lineHeight;
    wide=right-left;tall=bottom-top;return wide>0&&tall>0;
}
